SELECT counts.breakdown_value AS `context.columns.breakdown_value`, tuple(counts.visitors, counts.previous_visitors) AS `context.columns.visitors`, tuple(counts.views, counts.previous_views) AS `context.columns.views`, tuple(bounce.bounce_rate, bounce.previous_bounce_rate) AS `context.columns.bounce_rate`, divide(`context.columns.visitors`.1, sum(`context.columns.visitors`.1) OVER ()) AS `context.columns.ui_fill_fraction` FROM (SELECT nullIf(toString(events.properties.`$pathname`), '') AS breakdown_value, uniqIf(if(not(empty(events__override.distinct_id)), events__override.person_id, events.person_id), and(greaterOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))))) AS visitors, uniqIf(if(not(empty(events__override.distinct_id)), events__override.person_id, events.person_id), 0) AS previous_visitors, countIf(and(greaterOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))))) AS views, countIf(0) AS previous_views FROM events_json AS events LEFT OUTER JOIN (SELECT argMax(person_distinct_id_overrides.person_id, person_distinct_id_overrides.version) AS person_id, person_distinct_id_overrides.distinct_id AS distinct_id FROM person_distinct_id_overrides WHERE equals(person_distinct_id_overrides.team_id, TEAM_ID) GROUP BY person_distinct_id_overrides.distinct_id HAVING equals(argMax(person_distinct_id_overrides.is_deleted, person_distinct_id_overrides.version), 0) SETTINGS optimize_aggregation_in_order=1) AS events__override ON equals(events.distinct_id, events__override.distinct_id) WHERE and(equals(events.team_id, TEAM_ID), and(isNotNull(toUInt128(toUUIDOrNull(events.properties.`$session_id`))), or(equals(events.event, '$pageview'), equals(events.event, '$screen')), or(and(greaterOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')))), 0), 1)) GROUP BY breakdown_value) AS counts LEFT JOIN (SELECT sessions.`$entry_pathname` AS breakdown_value, avgIf(sessions.`$is_bounce`, and(greaterOrEquals(sessions.`$start_timestamp`, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(sessions.`$start_timestamp`, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))))) AS bounce_rate, avgIf(sessions.`$is_bounce`, 0) AS previous_bounce_rate FROM (SELECT path(argMinMerge(raw_sessions_v3.entry_url)) AS `$entry_pathname`, if(equals(uniqUpToMerge(1)(raw_sessions_v3.page_screen_uniq_up_to), 0), NULL, not(or(greaterOrEquals(uniqUpToMerge(1)(raw_sessions_v3.page_screen_uniq_up_to), 2), max(raw_sessions_v3.has_autocapture), greaterOrEquals(dateDiff('second', min(toTimeZone(raw_sessions_v3.min_timestamp, 'UTC')), max(toTimeZone(raw_sessions_v3.max_timestamp, 'UTC'))), 10)))) AS `$is_bounce`, min(toTimeZone(raw_sessions_v3.min_timestamp, 'UTC')) AS `$start_timestamp`, uniqMerge(raw_sessions_v3.pageview_uniq) AS `$pageview_count`, uniqMerge(raw_sessions_v3.screen_uniq) AS `$screen_count`, raw_sessions_v3.session_id_v7 AS session_id_v7 FROM raw_sessions_v3 WHERE and(equals(raw_sessions_v3.team_id, TEAM_ID), greaterOrEquals(raw_sessions_v3.session_timestamp, minus(assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC')), toIntervalDay(3))), lessOrEquals(raw_sessions_v3.session_timestamp, plus(assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')), toIntervalDay(3)))) GROUP BY raw_sessions_v3.session_id_v7) AS sessions WHERE and(or(and(greaterOrEquals(sessions.`$start_timestamp`, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(sessions.`$start_timestamp`, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')))), 0), or(greater(sessions.`$pageview_count`, 0), greater(sessions.`$screen_count`, 0)), 1) GROUP BY breakdown_value) AS bounce ON equals(counts.breakdown_value, bounce.breakdown_value) WHERE isNotNull(counts.breakdown_value) ORDER BY `context.columns.visitors` DESC, `context.columns.views` DESC, `context.columns.breakdown_value` ASC LIMIT 100
